import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../app/theme/app_colors.dart';
import '../../../app/theme/app_typography.dart';
import '../../../core/widgets/somna_card.dart';
import '../../../shared/models/sleep_insight.dart';
import '../../../shared/providers/sleep_tracker_provider.dart';
import '../../achievements/presentation/widgets/cyberdeck_trophy_card.dart';

/// The Sleep Insights screen showing explainable, transparent observations
/// generated by the deterministic [InsightEngine] and sleep hygiene principles.
class InsightsScreen extends StatelessWidget {
  const InsightsScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final tracker = context.watch<SleepTrackerProvider>();
    final insights = tracker.insights;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Sleep Insights'),
      ),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 10, 16, 96),
          children: [
            // Cyberdeck Milestone Trophy Vault
            CyberdeckTrophyCard(
              sessions: tracker.completedSessions,
              stats: tracker.weeklyStats,
            ),
            const SizedBox(height: 18),

            Text(
              'PERSONALIZED PATTERNS',
              style:
                  AppTypography.labelSmall(isDark).copyWith(letterSpacing: 1.1),
            ),
            const SizedBox(height: 8),
            if (insights.isEmpty)
              _buildEmptyState(isDark)
            else
              ...insights.map((insight) => Padding(
                    padding: const EdgeInsets.only(bottom: 10),
                    child: _buildInsightCard(insight, isDark),
                  )),
            const SizedBox(height: 14),
            Text(
              'FOUNDATIONAL SLEEP HABITS',
              style:
                  AppTypography.labelSmall(isDark).copyWith(letterSpacing: 1.1),
            ),
            const SizedBox(height: 12),
            _buildTipCard(
              title: 'Anchor Your Wake Time',
              description:
                  'Waking up at the same time each day—even on weekends—sets your circadian rhythm and improves nighttime sleep drive.',
              icon: Icons.alarm_rounded,
              color: isDark ? const Color(0xFFA3A3A3) : const Color(0xFF525252),
              isDark: isDark,
            ),
            const SizedBox(height: 12),
            _buildTipCard(
              title: 'Wind-Down Buffer Zone',
              description:
                  'Allow 30 to 60 minutes before bed with dim lighting and relaxing activities (reading, gentle stretching) to signal melatonin release.',
              icon: Icons.nightlight_round,
              color: isDark ? AppColors.primary : AppColors.primaryDark,
              isDark: isDark,
            ),
            const SizedBox(height: 12),
            _buildTipCard(
              title: 'Keep Room Cool & Dark',
              description:
                  'Body temperature naturally dips during sleep. A room temperature around 18–20°C (65–68°F) prevents nighttime awakenings.',
              icon: Icons.thermostat_rounded,
              color: isDark ? AppColors.primary : AppColors.primaryDark,
              isDark: isDark,
            ),
            const SizedBox(height: 24),
          ],
        ),
      ),
    );
  }

  Widget _buildInsightCard(SleepInsight insight, bool isDark) {
    final effectiveColor = isDark
        ? insight.accentColor
        : (insight.accentColor == AppColors.primary ||
                insight.accentColor == AppColors.positive
            ? AppColors.primaryDark
            : const Color(0xFF525252));

    return SomnaCard(
      padding: const EdgeInsets.all(14),
      border: Border.all(
        color: isDark
            ? effectiveColor.withValues(alpha: 0.35)
            : const Color(0xFFE5E5E5),
        width: 1.2,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: isDark
                      ? effectiveColor.withValues(alpha: 0.15)
                      : const Color(0xFFE5E5E5),
                  borderRadius: BorderRadius.circular(6),
                ),
                child: Icon(insight.icon, color: effectiveColor, size: 20),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  insight.title,
                  style: AppTypography.titleMedium(isDark),
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Text(
            insight.message,
            style: AppTypography.bodyMedium(isDark).copyWith(height: 1.45),
          ),
          const SizedBox(height: 16),

          // Transparent Calculation Explanation Box
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: isDark ? AppColors.darkElevated : AppColors.lightElevated,
              borderRadius: BorderRadius.circular(10),
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(Icons.info_outline_rounded,
                    size: 16,
                    color: isDark
                        ? AppColors.textMutedDark
                        : AppColors.textMutedLight),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    insight.calculationExplanation,
                    style: AppTypography.bodySmall(isDark).copyWith(
                      color: isDark
                          ? AppColors.textSecondaryDark
                          : AppColors.textSecondaryLight,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildTipCard({
    required String title,
    required String description,
    required IconData icon,
    required Color color,
    required bool isDark,
  }) {
    return SomnaCard(
      padding: const EdgeInsets.all(14),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: isDark
                  ? color.withValues(alpha: 0.15)
                  : const Color(0xFFE5E5E5),
              borderRadius: BorderRadius.circular(6),
            ),
            child: Icon(icon, color: color, size: 18),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title, style: AppTypography.titleSmall(isDark)),
                const SizedBox(height: 4),
                Text(
                  description,
                  style: AppTypography.bodySmall(isDark).copyWith(height: 1.4),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildEmptyState(bool isDark) {
    return SomnaCard(
      padding: const EdgeInsets.all(24),
      child: Center(
        child: Column(
          children: [
            Icon(Icons.auto_awesome_rounded,
                size: 36,
                color: isDark ? AppColors.primary : AppColors.primaryDark),
            const SizedBox(height: 12),
            Text('No Insights Available Yet',
                style: AppTypography.titleSmall(isDark)),
            const SizedBox(height: 6),
            Text(
              'Record at least 3 completed sleep sessions to generate evidence-backed sleep observations.',
              textAlign: TextAlign.center,
              style: AppTypography.bodySmall(isDark),
            ),
          ],
        ),
      ),
    );
  }
}
